  9	import java.util.Objects;
 10	
 11	public class App {
 12	  private static final Logger logger = LoggerFactory.getLogger(App.class);
 13	
 14	  public static void main(String[] args) {
 15	    String dbUrl = Objects.requireNonNull(System.getenv("DB_URL"), "DB_URL environment variable is required");
 16	    String dbUser = Objects.requireNonNull(System.getenv("DB_USER"), "DB_USER environment variable is required");
 17	    String dbPassword = Objects.requireNonNull(System.getenv("DB_PASSWORD"), "DB_PASSWORD environment variable is required");
 18	
 19	    String portEnv = System.getenv("PORT");
 20	    int port = portEnv != null ? Integer.parseInt(portEnv) : 7070;
 21	
 22	    logger.info("Initializing database...");
 23	    Database.init(dbUrl, dbUser, dbPassword);
 24	
 25	    logger.info("Starting application on port {}", port);
 26	    Javalin app = Javalin.create().start(port);
 27	
 28	    setupRoutes(app);
 29	
 30	    logger.info("Application started successfully");
 31	
 32	    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 33	      logger.info("Shutting down application...");
 34	      app.stop();
 35	      Database.close();
 36	    }));
 37	  }
 38	
 39	  private static void setupRoutes(Javalin app) {
 40	    app.get("/rooms", RoomController::getRooms);
 41	
 42	    app.post("/reservations", ReservationController::createReservation);
 43	    app.get("/reservations/{id}", ReservationController::getReservation);
 44	    app.post("/reservations/{id}/confirmation", ReservationController::confirmReservation);
 45	    app.post("/reservations/{id}/cancellation", ReservationController::cancelReservation);
 46	    app.post("/reservations/{id}/check-in", ReservationController::checkIn);
 47	    app.post("/reservations/{id}/check-out", ReservationController::checkOut);
 48	    app.get("/reservations/{id}/document", ReservationController::getReceipt);
 49	
 50	    app.get("/messages", MessageController::getMessages);
 51	
 52	    app.get("/reports/occupancy", ReportController::getOccupancyReport);
 53	    app.get("/reports/revenue", ReportController::getRevenueReport);
 54	  }
 55	}
