 69	
 70	import java.math.BigDecimal;
 71	import java.time.LocalDate;
 72	import java.time.format.DateTimeFormatter;
 73	
 74	public class ReservationController {
 75	  private static final Logger logger = LoggerFactory.getLogger(ReservationController.class);
 76	  private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 77	
 78	  public static void createReservation(Context ctx) {
 79	    try {
 80	      ReservationRequest request = ctx.bodyAsClass(ReservationRequest.class);
 81	
 82	      if (request.roomNumber == 0 || request.guestName == null || request.guestEmail == null ||
 83	          request.guestCpf == null || request.checkIn == null || request.checkOut == null ||
 84	          request.ratePlan == null) {
 85	        ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
 86	        return;
 87	      }
 88	
 89	      LocalDate checkIn = parseDate(request.checkIn);
 90	      LocalDate checkOut = parseDate(request.checkOut);
 91	
 92	      if (checkIn == null || checkOut == null) {
 93	        ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
 94	        return;
 95	      }
 96	
 97	      RatePlan ratePlan = RatePlan.valueOf(request.ratePlan.toUpperCase());
 98	
 99	      try {
100	        Reservation reservation = ReservationService.createReservation(
101	            request.roomNumber, request.guestName, request.guestEmail, request.guestCpf,
102	            checkIn, checkOut, request.guests, ratePlan);
103	
104	        ctx.status(201).json(ReservationConverter.toResponse(reservation));
105	      } catch (IllegalArgumentException e) {
106	        handleServiceException(ctx, e.getMessage());
107	      }
108	    } catch (IllegalArgumentException e) {
109	      ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
110	    } catch (Exception e) {
111	      logger.error("Error creating reservation", e);
112	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to create reservation"));
113	    }
114	  }
115	
116	  public static void getReservation(Context ctx) {
117	    try {
118	      long id = ctx.pathParamAsClass("id", Long.class).get();
119	      Reservation reservation = ReservationRepository.findById(id);
120	
121	      if (reservation == null) {
122	        ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
123	        return;
124	      }
125	
126	      ctx.json(ReservationConverter.toResponse(reservation));
127	    } catch (Exception e) {
128	      logger.error("Error fetching reservation", e);
129	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to fetch reservation"));
130	    }
131	  }
