145	        ctx.json(ReservationConverter.toResponse(confirmed));
146	      } catch (IllegalArgumentException e) {
147	        handleServiceException(ctx, e.getMessage());
148	      }
149	    } catch (Exception e) {
150	      logger.error("Error confirming reservation", e);
151	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to confirm reservation"));
