186	
187	  public static void cancelReservation(Context ctx) {
188	    try {
189	      long id = ctx.pathParamAsClass("id", Long.class).get();
190	
191	      try {
192	        Reservation cancelled = ReservationService.cancelReservation(id);
193	        ctx.json(ReservationConverter.toResponse(cancelled));
194	      } catch (IllegalArgumentException e) {
195	        handleServiceException(ctx, e.getMessage());
196	      }
197	    } catch (Exception e) {
198	      logger.error("Error cancelling reservation", e);
199	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to cancel reservation"));
200	    }
201	  }
202	
203	  public static void getReceipt(Context ctx) {
204	    try {
205	      long id = ctx.pathParamAsClass("id", Long.class).get();
206	      Reservation reservation = ReservationRepository.findById(id);
207	
208	      if (reservation == null) {
209	        ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
210	        return;
211	      }
212	
213	      if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) <= 0) {
214	        ctx.status(404).json(new ErrorResponse("RECEIPT_NOT_FOUND", "Receipt not found"));
215	        return;
216	      }
217	
218	      var room = RoomRepository.findByNumber(reservation.getRoomNumber());
219	
220	      var receipt = new ReceiptResponse(
221	          "Comprovante de reserva",
222	          reservation.getId(),
223	          reservation.getGuestName(),
224	          reservation.getGuestCpf(),
225	          reservation.getRoomNumber(),
226	          room.getType(),
227	          reservation.getCheckIn().format(DATE_FORMATTER),
228	          reservation.getCheckOut().format(DATE_FORMATTER),
229	          reservation.getNights(),
230	          reservation.getSubtotal().doubleValue(),
231	          reservation.getDiscount().doubleValue(),
232	          reservation.getTotal().doubleValue()
233	      );
234	
235	      ctx.json(receipt);
236	    } catch (Exception e) {
237	      logger.error("Error fetching receipt", e);
238	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to fetch receipt"));
239	    }
240	  }
241	
242	  private static LocalDate parseDate(String dateStr) {
243	    try {
244	      return LocalDate.parse(dateStr, DATE_FORMATTER);
245	    } catch (Exception e) {
246	      return null;
247	    }
248	  }
249	
250	  private static void handleServiceException(Context ctx, String error) {
251	    switch (error) {
252	      case "ROOM_NOT_FOUND" -> ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
253	      case "RESERVATION_NOT_FOUND" ->
254	          ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
255	      case "ROOM_UNAVAILABLE" ->
256	          ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
257	      case "CAPACITY_EXCEEDED" ->
258	          ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
259	      case "OPERATION_NOT_ALLOWED" ->
260	          ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed for the current reservation status"));
261	      case "INVALID_REQUEST" ->
262	          ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
263	      default ->
264	          ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "An error occurred"));
265	    }
266	  }
267	}
268	package com.pousada.marealta.service;
269	
270	import com.pousada.marealta.domain.Reservation;
271	import com.pousada.marealta.domain.ReservationStatus;
272	import com.pousada.marealta.domain.RatePlan;
273	import com.pousada.marealta.domain.Room;
274	import com.pousada.marealta.notification.NotificationService;
275	import com.pousada.marealta.repository.ReservationRepository;
276	import com.pousada.marealta.repository.RoomRepository;
277	
278	import java.math.BigDecimal;
279	import java.sql.SQLException;
280	import java.time.LocalDate;
281	
282	public class ReservationService {
283	
284	  public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
285	      String guestCpf, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan)
286	      throws SQLException {
287	
288	    Room room = RoomRepository.findByNumber(roomNumber);
289	    if (room == null) {
290	      throw new IllegalArgumentException("ROOM_NOT_FOUND");
291	    }
292	
293	    if (guests < 1) {
294	      throw new IllegalArgumentException("INVALID_REQUEST");
295	    }
296	
297	    if (guests > room.getCapacity()) {
298	      throw new IllegalArgumentException("CAPACITY_EXCEEDED");
299	    }
300	
301	    if (!checkIn.isBefore(checkOut)) {
302	      throw new IllegalArgumentException("INVALID_REQUEST");
303	    }
304	
305	    checkRoomAvailability(roomNumber, checkIn, checkOut);
306	
307	    int nights = PricingCalculator.calculateNights(checkIn, checkOut);
308	    BigDecimal subtotal = PricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
309	    BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan.getDiscountRate());
310	    BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
311	
312	    Reservation reservation = new Reservation(0, roomNumber, guestName, guestEmail, guestCpf,
313	        checkIn, checkOut, guests, ratePlan, nights, subtotal, discount, total);
314	
315	    return ReservationRepository.create(reservation);
316	  }
317	
318	  public static Reservation confirmReservation(long id, BigDecimal amountPaid) throws SQLException {
319	    Reservation reservation = ReservationRepository.findById(id);
320	    if (reservation == null) {
321	      throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
322	    }
323	
324	    if (reservation.getStatus() != ReservationStatus.PENDING) {
325	      throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
326	    }
327	
328	    reservation.setStatus(ReservationStatus.CONFIRMED);
329	    reservation.setAmountPaid(amountPaid);
330	    ReservationRepository.update(reservation);
331	
332	    NotificationService.notifyReservationConfirmed(reservation);
333	
334	    return reservation;
335	  }
336	
337	  public static Reservation checkIn(long id) throws SQLException {
338	    Reservation reservation = ReservationRepository.findById(id);
339	    if (reservation == null) {
340	      throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
341	    }
342	
343	    if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
344	      throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
345	    }
346	
347	    reservation.setStatus(ReservationStatus.CHECKED_IN);
348	    ReservationRepository.update(reservation);
349	
350	    return reservation;
351	  }
352	
353	  public static Reservation checkOut(long id) throws SQLException {
354	    Reservation reservation = ReservationRepository.findById(id);
355	    if (reservation == null) {
356	      throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
357	    }
358	
359	    if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
360	      throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
361	    }
362	
363	    reservation.setStatus(ReservationStatus.CHECKED_OUT);
364	    ReservationRepository.update(reservation);
365	
366	    return reservation;
367	  }
368	
369	  public static Reservation cancelReservation(long id) throws SQLException {
370	    Reservation reservation = ReservationRepository.findById(id);
371	    if (reservation == null) {
372	      throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
373	    }
374	
375	    ReservationStatus status = reservation.getStatus();
376	    if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
377	      throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
378	    }
379	
380	    reservation.setStatus(ReservationStatus.CANCELLED);
381	
382	    if (status == ReservationStatus.CONFIRMED) {
383	      if (reservation.getRatePlan() == RatePlan.STANDARD) {
384	        reservation.setRefund(reservation.getAmountPaid());
385	      } else {
386	        reservation.setRefund(BigDecimal.ZERO);
387	      }
388	    } else {
389	      reservation.setRefund(BigDecimal.ZERO);
390	    }
391	
392	    ReservationRepository.update(reservation);
393	
394	    if (status == ReservationStatus.CONFIRMED) {
395	      NotificationService.notifyReservationCancelled(reservation);
396	    }
397	
398	    return reservation;
399	  }
400	
401	  private static void checkRoomAvailability(int roomNumber, LocalDate checkIn, LocalDate checkOut)
402	      throws SQLException {
403	    LocalDate currentDate = checkIn;
404	    while (currentDate.isBefore(checkOut)) {
405	      var reservations = ReservationRepository.findByRoomAndDate(roomNumber, currentDate);
406	      if (!reservations.isEmpty()) {
407	        throw new IllegalArgumentException("ROOM_UNAVAILABLE");
408	      }
409	      currentDate = currentDate.plusDays(1);
410	    }
411	  }
412	}

