189	      long id = ctx.pathParamAsClass("id", Long.class).get();
190	
191	      try {
192	        Reservation cancelled = ReservationService.cancelReservation(id);
193	        ctx.json(ReservationConverter.toResponse(cancelled));
194	      } catch (IllegalArgumentException e) {
195	        handleServiceException(ctx, e.getMessage());
196	      }
197	    } catch (Exception e) {
198	      logger.error("Error cancelling reservation", e);
199	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to cancel reservation"));
200	    }
201	  }
202	
203	  public static void getReceipt(Context ctx) {
204	    try {
205	      long id = ctx.pathParamAsClass("id", Long.class).get();
206	      Reservation reservation = ReservationRepository.findById(id);
207	
208	      if (reservation == null) {
209	        ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
210	        return;
211	      }
212	
213	      if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) <= 0) {
214	        ctx.status(404).json(new ErrorResponse("RECEIPT_NOT_FOUND", "Receipt not found"));
215	        return;
216	      }
217	
218	      var room = RoomRepository.findByNumber(reservation.getRoomNumber());
219	
220	      var receipt = new ReceiptResponse(
221	          "Comprovante de reserva",
222	          reservation.getId(),
223	          reservation.getGuestName(),
224	          reservation.getGuestCpf(),
225	          reservation.getRoomNumber(),
226	          room.getType(),
227	          reservation.getCheckIn().format(DATE_FORMATTER),
228	          reservation.getCheckOut().format(DATE_FORMATTER),
229	          reservation.getNights(),
230	          reservation.getSubtotal().doubleValue(),
231	          reservation.getDiscount().doubleValue(),
232	          reservation.getTotal().doubleValue()
233	      );
234	
235	      ctx.json(receipt);
236	    } catch (Exception e) {
237	      logger.error("Error fetching receipt", e);
238	      ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Failed to fetch receipt"));
239	    }
240	  }
241	
242	  private static LocalDate parseDate(String dateStr) {
243	    try {
244	      return LocalDate.parse(dateStr, DATE_FORMATTER);
245	    } catch (Exception e) {
246	      return null;
247	    }
248	  }
249	
250	  private static void handleServiceException(Context ctx, String error) {
251	    switch (error) {
252	      case "ROOM_NOT_FOUND" -> ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
253	      case "RESERVATION_NOT_FOUND" ->
254	          ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
255	      case "ROOM_UNAVAILABLE" ->
256	          ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
257	      case "CAPACITY_EXCEEDED" ->
258	          ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
259	      case "OPERATION_NOT_ALLOWED" ->
260	          ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "This operation is not allowed for the current reservation status"));
261	      case "INVALID_REQUEST" ->
262	          ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
263	      default ->
264	          ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "An error occurred"));
265	    }
266	  }
