192	public class MessageRepository {
193	  public static Message save(String channel, String to, String subject, String body) throws SQLException {
194	    String sql = "INSERT INTO messages (channel, \"to\", subject, body) VALUES (?, ?, ?, ?) RETURNING id";
195	
196	    try (Connection conn = Database.getConnection();
197	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
198	      pstmt.setString(1, channel);
199	      pstmt.setString(2, to);
200	      pstmt.setString(3, subject);
201	      pstmt.setString(4, body);
202	
203	      try (ResultSet rs = pstmt.executeQuery()) {
204	        if (rs.next()) {
205	          long id = rs.getLong("id");
206	          return findById(id);
207	        }
208	      }
209	    }
210	    throw new SQLException("Failed to save message");
211	  }
212	
213	  public static Message findById(long id) throws SQLException {
214	    String sql = "SELECT id, channel, \"to\", subject, body FROM messages WHERE id = ?";
215	
216	    try (Connection conn = Database.getConnection();
217	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
218	      pstmt.setLong(1, id);
219	      try (ResultSet rs = pstmt.executeQuery()) {
220	        if (rs.next()) {
221	          return new Message(
222	              rs.getLong("id"),
223	              rs.getString("channel"),
224	              rs.getString("to"),
225	              rs.getString("subject"),
226	              rs.getString("body")
227	          );
228	        }
229	      }
230	    }
231	    return null;
232	  }
233	
234	  public static List<Message> findAll() throws SQLException {
235	    List<Message> messages = new ArrayList<>();
236	    try (Connection conn = Database.getConnection();
237	         Statement stmt = conn.createStatement();
238	         ResultSet rs = stmt.executeQuery("SELECT id, channel, \"to\", subject, body FROM messages ORDER BY id")) {
239	      while (rs.next()) {
240	        messages.add(new Message(
241	            rs.getLong("id"),
242	            rs.getString("channel"),
243	            rs.getString("to"),
244	            rs.getString("subject"),
245	            rs.getString("body")
246	        ));
247	      }
248	    }
249	    return messages;
250	  }
251	}

