  1	package com.pousada.marealta.service;
  2	
  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	import java.time.Month;
  7	
  8	public class PricingCalculator {
  9	  private static final BigDecimal PEAK_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
 10	  private static final RoundingMode ROUNDING_MODE = RoundingMode.HALF_EVEN;
 11	
 12	  public static boolean isPeakSeason(LocalDate date) {
 13	    Month month = date.getMonth();
 14	    int dayOfMonth = date.getDayOfMonth();
 15	
 16	    if (month == Month.JULY) return true;
 17	    if (month == Month.DECEMBER) return true;
 18	    if (month == Month.JANUARY) return true;
 19	    if (month == Month.FEBRUARY) return true;
 20	
 21	    return false;
 22	  }
 23	
 24	  public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
 25	    if (isPeakSeason(date)) {
 26	      return baseRate.multiply(PEAK_SEASON_MULTIPLIER).setScale(2, ROUNDING_MODE);
 27	    }
 28	    return baseRate.setScale(2, ROUNDING_MODE);
 29	  }
 30	
 31	  public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
 32	    BigDecimal subtotal = BigDecimal.ZERO;
 33	    LocalDate currentDate = checkIn;
 34	
 35	    while (currentDate.isBefore(checkOut)) {
 36	      BigDecimal nightlyRate = calculateNightlyRate(baseRate, currentDate);
 37	      subtotal = subtotal.add(nightlyRate);
 38	      currentDate = currentDate.plusDays(1);
 39	    }
 40	
 41	    return subtotal.setScale(2, ROUNDING_MODE);
 42	  }
 43	
 44	  public static BigDecimal calculateDiscount(BigDecimal subtotal, double discountRate) {
 45	    if (discountRate == 0.0) {
 46	      return BigDecimal.ZERO.setScale(2, ROUNDING_MODE);
 47	    }
