394	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
395	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
396	        "FROM reservations WHERE id = ?";
