423	  public static List<Reservation> findByRoomAndDate(int roomNumber, LocalDate date) throws SQLException {
424	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
425	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
426	        "FROM reservations WHERE room_number = ? AND check_in <= ? AND check_out > ? " +
427	        "AND status != ?";
