450	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
451	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
452	        "FROM reservations WHERE check_in >= ? AND check_in < ? " +
453	        "AND status IN (?, ?, ?) " +
454	        "ORDER BY check_in ASC, id ASC";
455	
456	    List<Reservation> reservations = new ArrayList<>();
457	    try (Connection conn = Database.getConnection();
