114	        cpf.substring(6, 9) + "-" + cpf.substring(9);
115	  }
116	
117	  public static String formatMoney(BigDecimal value) {
118	    return "R$ " + MONEY_FORMATTER.format(value);
119	  }
120	
121	  public static String formatDate(java.time.LocalDate date) {
122	    return date.format(DATE_FORMATTER);
123	  }
124	}
