139	public class ReportService {
140	  private static final int TOTAL_ROOMS = 5;
141	
142	  public static String generateOccupancyReport(LocalDate date) throws SQLException {
143	    List<Reservation> reservations = getReservationsForDate(date);
144	
145	    StringBuilder csv = new StringBuilder();
146	    csv.append("room,type,reservation,check_in,check_out\n");
147	
148	    var rooms = RoomRepository.findAll();
149	    for (var room : rooms) {
150	      var reservation = reservations.stream()
151	          .filter(r -> r.getRoomNumber() == room.getNumber())
152	          .findFirst()
153	          .orElse(null);
154	
155	      if (reservation != null && reservation.getStatus() != ReservationStatus.CANCELLED) {
156	        csv.append(reservation.getRoomNumber()).append(",");
157	        csv.append(room.getType()).append(",");
158	        csv.append(reservation.getId()).append(",");
159	        csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
160	        csv.append(formatDateForCsv(reservation.getCheckOut())).append("\n");
161	      }
162	    }
163	
164	    long occupiedRooms = reservations.stream()
165	        .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
166	        .count();
167	
168	    csv.append("total,").append(occupiedRooms).append("/").append(TOTAL_ROOMS);
169	
170	    return csv.toString();
171	  }
172	
173	  public static String generateRevenueReport(String month) throws SQLException {
174	    YearMonth yearMonth = YearMonth.parse(month, DateTimeFormatter.ofPattern("yyyy-MM"));
175	    List<Reservation> reservations = ReservationRepository.findByMonthStarting(yearMonth.getYear(), yearMonth.getMonthValue());
176	
177	    StringBuilder csv = new StringBuilder();
178	    csv.append("reservation,room,check_in,check_out,status,amount\n");
179	
180	    BigDecimal total = BigDecimal.ZERO;
181	
182	    for (Reservation reservation : reservations) {
183	      BigDecimal amount = calculateAmount(reservation);
184	
185	      csv.append(reservation.getId()).append(",");
186	      csv.append(reservation.getRoomNumber()).append(",");
187	      csv.append(formatDateForCsv(reservation.getCheckIn())).append(",");
188	      csv.append(formatDateForCsv(reservation.getCheckOut())).append(",");
189	      csv.append(reservation.getStatus().name()).append(",");
190	      csv.append(formatNumberForCsv(amount)).append("\n");
191	
192	      total = total.add(amount);
193	    }
194	
195	    csv.append("total,,,,").append(formatNumberForCsv(total));
196	
197	    return csv.toString();
198	  }
199	
200	  private static BigDecimal calculateAmount(Reservation reservation) {
201	    BigDecimal amount = reservation.getAmountPaid();
202	
203	    if (reservation.getRefund() != null && reservation.getRefund().compareTo(BigDecimal.ZERO) > 0) {
204	      amount = amount.subtract(reservation.getRefund());
205	    }
206	
207	    return amount;
208	  }
209	
210	  private static List<Reservation> getReservationsForDate(LocalDate date) throws SQLException {
211	    var rooms = RoomRepository.findAll();
212	    var occupiedReservations = new java.util.ArrayList<Reservation>();
213	
214	    for (var room : rooms) {
215	      var reservations = ReservationRepository.findByRoomAndDate(room.getNumber(), date);
216	      occupiedReservations.addAll(reservations);
217	    }
218	
219	    return occupiedReservations;
220	  }
221	
222	  private static String formatDateForCsv(LocalDate date) {
223	    return date.format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
224	  }
225	
226	  private static String formatNumberForCsv(BigDecimal number) {
227	    return number.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
228	  }
229	}
