247	  public static void init(String dbUrl, String dbUser, String dbPassword) {
248	    if (dataSource != null) {
249	      return;
250	    }
251	
252	    HikariConfig config = new HikariConfig();
253	    config.setJdbcUrl(dbUrl);
254	    config.setUsername(dbUser);
255	    config.setPassword(dbPassword);
256	    config.setMaximumPoolSize(10);
257	    config.setMinimumIdle(2);
258	    config.setConnectionTimeout(30000);
259	    config.setIdleTimeout(600000);
260	    config.setMaxLifetime(1800000);
261	
262	    dataSource = new HikariDataSource(config);
263	    logger.info("Database connection pool initialized");
264	
265	    runMigrations();
266	  }
267	
268	  private static void runMigrations() {
269	    try (Connection conn = dataSource.getConnection()) {
270	      Migration.migrate(conn);
271	      logger.info("Database migrations completed");
272	    } catch (SQLException e) {
273	      logger.error("Error running migrations", e);
274	      throw new RuntimeException("Failed to initialize database", e);
275	    }
276	  }
