361	public class ReservationRepository {
362	  public static Reservation create(Reservation reservation) throws SQLException {
363	    String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, " +
364	        "check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) " +
365	        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
366	
367	    try (Connection conn = Database.getConnection();
368	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
369	      pstmt.setInt(1, reservation.getRoomNumber());
370	      pstmt.setString(2, reservation.getGuestName());
371	      pstmt.setString(3, reservation.getGuestEmail());
372	      pstmt.setString(4, reservation.getGuestCpf());
373	      pstmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
374	      pstmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
375	      pstmt.setInt(7, reservation.getGuests());
376	      pstmt.setString(8, reservation.getRatePlan().name());
377	      pstmt.setInt(9, reservation.getNights());
378	      pstmt.setBigDecimal(10, reservation.getSubtotal());
379	      pstmt.setBigDecimal(11, reservation.getDiscount());
380	      pstmt.setBigDecimal(12, reservation.getTotal());
381	      pstmt.setString(13, reservation.getStatus().name());
382	      pstmt.setBigDecimal(14, reservation.getAmountPaid());
383	
384	      try (ResultSet rs = pstmt.executeQuery()) {
385	        if (rs.next()) {
386	          return findById(rs.getLong("id"));
387	        }
388	      }
389	    }
390	    throw new SQLException("Failed to create reservation");
391	  }
392	
393	  public static Reservation findById(long id) throws SQLException {
394	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
395	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
396	        "FROM reservations WHERE id = ?";
397	
398	    try (Connection conn = Database.getConnection();
399	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
400	      pstmt.setLong(1, id);
401	      try (ResultSet rs = pstmt.executeQuery()) {
402	        if (rs.next()) {
403	          return mapToReservation(rs);
404	        }
405	      }
406	    }
407	    return null;
408	  }
409	
410	  public static void update(Reservation reservation) throws SQLException {
411	    String sql = "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?";
412	
413	    try (Connection conn = Database.getConnection();
414	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
415	      pstmt.setString(1, reservation.getStatus().name());
416	      pstmt.setBigDecimal(2, reservation.getAmountPaid());
417	      pstmt.setBigDecimal(3, reservation.getRefund());
418	      pstmt.setLong(4, reservation.getId());
419	      pstmt.executeUpdate();
420	    }
421	  }
422	
423	  public static List<Reservation> findByRoomAndDate(int roomNumber, LocalDate date) throws SQLException {
424	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
425	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
426	        "FROM reservations WHERE room_number = ? AND check_in <= ? AND check_out > ? " +
427	        "AND status != ?";
428	
429	    List<Reservation> reservations = new ArrayList<>();
430	    try (Connection conn = Database.getConnection();
431	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
432	      pstmt.setInt(1, roomNumber);
433	      pstmt.setDate(2, Date.valueOf(date));
434	      pstmt.setDate(3, Date.valueOf(date));
435	      pstmt.setString(4, ReservationStatus.CANCELLED.name());
436	
437	      try (ResultSet rs = pstmt.executeQuery()) {
438	        while (rs.next()) {
439	          reservations.add(mapToReservation(rs));
440	        }
441	      }
442	    }
443	    return reservations;
444	  }
445	
446	  public static List<Reservation> findByMonthStarting(int year, int month) throws SQLException {
447	    LocalDate monthStart = LocalDate.of(year, month, 1);
448	    LocalDate monthEnd = monthStart.plusMonths(1);
449	
450	    String sql = "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, " +
451	        "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund " +
452	        "FROM reservations WHERE check_in >= ? AND check_in < ? " +
453	        "AND status IN (?, ?, ?) " +
454	        "ORDER BY check_in ASC, id ASC";
455	
456	    List<Reservation> reservations = new ArrayList<>();
457	    try (Connection conn = Database.getConnection();
458	         PreparedStatement pstmt = conn.prepareStatement(sql)) {
459	      pstmt.setDate(1, Date.valueOf(monthStart));
460	      pstmt.setDate(2, Date.valueOf(monthEnd));
461	      pstmt.setString(3, ReservationStatus.CONFIRMED.name());
462	      pstmt.setString(4, ReservationStatus.CHECKED_IN.name());
463	      pstmt.setString(5, ReservationStatus.CHECKED_OUT.name());
464	
465	      try (ResultSet rs = pstmt.executeQuery()) {
466	        while (rs.next()) {
467	          reservations.add(mapToReservation(rs));
468	        }
469	      }
470	    }
471	    return reservations;
472	  }
473	
474	  private static Reservation mapToReservation(ResultSet rs) throws SQLException {
475	    Reservation reservation = new Reservation(
476	        rs.getLong("id"),
477	        rs.getInt("room_number"),
478	        rs.getString("guest_name"),
479	        rs.getString("guest_email"),
480	        rs.getString("guest_cpf"),
481	        rs.getDate("check_in").toLocalDate(),
482	        rs.getDate("check_out").toLocalDate(),
483	        rs.getInt("guests"),
484	        RatePlan.valueOf(rs.getString("rate_plan")),
485	        rs.getInt("nights"),
486	        rs.getBigDecimal("subtotal"),
487	        rs.getBigDecimal("discount"),
488	        rs.getBigDecimal("total")
489	    );
490	    reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
491	    reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
492	    reservation.setRefund(rs.getBigDecimal("refund"));
493	    return reservation;
494	  }
495	}

